/* Scripture Launchpad — Doctrine & Covenants, part 4: sections 51-68 */
window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _dc = SLP.books.find(function(b){ return b.id === "dc"; });
if (!_dc) throw new Error("data/canon.js must load before dc-04-zion.js");
(_dc.chapters = _dc.chapters || []).push(
  { n:51, summary:"As the Colesville saints settled temporarily at Thompson, Ohio, the Lord gave Edward Partridge directions for organizing them under the law of consecration. Each man was to receive a portion equal according to his family, circumstances, wants, and needs, secured by a written deed that remained his as long as he was accounted worthy in the church. Surplus money and goods beyond what was needful were to be kept by the bishop in a storehouse for the poor and needy, and an agent was to manage funds honestly so the people could be one. The Lord consecrated the land to them for a little season and told them to act upon it as for years, and this would turn to their good. A faithful, just, and wise steward would enter into the joy of his Lord and inherit eternal life.",
    context:"Given through Joseph Smith in May 1831 as Edward Partridge organized the newly gathered Colesville saints in Ohio under the law of consecration.",
    keyVerses:[
      { ref:"D&C 51:9", text:"And let every man deal honestly, and be alike among this people, and receive alike, that ye may be one, even as I have commanded you." },
      { ref:"D&C 51:19", text:"And whoso is found a faithful, a just, and a wise steward shall enter into the joy of his Lord, and shall inherit eternal life." }
    ],
    takeaway:"Deal honestly with what you are given; faithful stewardship over your portion leads to the joy of the Lord.",
    quiz:[
      { q:"Who received directions to organize the gathered saints and appoint their portions?", choices:["Edward Partridge","Sidney Gilbert","Newel Knight","William W. Phelps"], a:0, why:"The Lord said Edward Partridge must receive directions how to organize the people and appoint every man his portion." },
      { q:"How were portions to be appointed among the people?", choices:["Each man received the same amount of money regardless of family size","Every man equal according to his family, circumstances, wants, and needs","Portions were drawn by lot each season","The earliest arrivals received the largest inheritances"], a:1, why:"Portions were to be appointed every man equal according to his family, circumstances, wants, and needs." },
      { q:"What promise did the Lord give to the faithful, just, and wise steward?", choices:["Riches in this life and freedom from trials","A double portion of consecrated land","That he would enter into the joy of his Lord and inherit eternal life","Permanent charge of the church storehouse"], a:2, why:"The Lord promised that whoso is found a faithful, just, and wise steward shall enter into the joy of his Lord and inherit eternal life." }
    ] },
  { n:52, summary:"A few days after the June 1831 conference, the Lord appointed more than two dozen elders to travel from Ohio to Missouri, the land he would consecrate for a remnant of Jacob and the heirs of the covenant. Joseph Smith and Sidney Rigdon were to lead the way, with Edward Partridge and Martin Harris accompanying them, while other elders went two by two along different routes, preaching only what the prophets and apostles had written and what the Comforter taught through the prayer of faith. The Lord gave a pattern for detecting deception, since Satan was abroad in the land: the contrite, the meek, and those bringing forth fruits were of God. Heman Basset's blessing was transferred to Simonds Ryder because of transgression, and the faithful were promised they would assemble and rejoice upon the land of Missouri, though it was then the land of their enemies.",
    context:"Given through Joseph Smith in June 1831, commissioning elders at Kirtland to travel in pairs to the land of Missouri.",
    keyVerses:[
      { ref:"D&C 52:10", text:"Let them go two by two, and thus let them preach by the way in every congregation, baptizing by water, and the laying on of the hands by the water's side." },
      { ref:"D&C 52:14", text:"And again, I will give unto you a pattern in all things, that ye may not be deceived; for Satan is abroad in the land, and he goeth forth deceiving the nations—" },
      { ref:"D&C 52:42", text:"And thus, even as I have said, if ye are faithful ye shall assemble yourselves together to rejoice upon the land of Missouri," }
    ],
    takeaway:"Follow the Lord's pattern and His appointed companions; faithful service brings fruit and guards against deception.",
    quiz:[
      { q:"Which two men were told to take their journey to Missouri as soon as preparations could be made?", choices:["Oliver Cowdery and David Whitmer","Parley P. Pratt and Orson Pratt","Thomas B. Marsh and Ezra Thayre","Joseph Smith and Sidney Rigdon"], a:3, why:"The Lord directed Joseph Smith and Sidney Rigdon to leave their homes and journey to the land of Missouri." },
      { q:"How were the elders instructed to preach as they traveled toward Missouri?", choices:["Two by two, saying only what the prophets and apostles had written and what the Comforter taught","Alone, each declaring his own new doctrines","Only after they arrived in Missouri","Through letters sent back to Kirtland"], a:0, why:"They were to go two by two, preaching none other things than the prophets and apostles wrote and what the Comforter taught through the prayer of faith." },
      { q:"According to the pattern in this section, how is a messenger recognized as being of God?", choices:["By performing signs on demand before congregations","By a contrite spirit, meek and edifying language, and obedience to the Lord's ordinances","By holding high office in the church","By predicting the exact day of the Lord's coming"], a:1, why:"The Lord taught that the contrite whose language is meek and edifies are of God if they obey His ordinances." }
    ] },
  { n:53, summary:"Sidney Gilbert had prayed to know his calling and election in the church, and the Lord answered that he must forsake the world. Gilbert was to take upon himself the ordination of an elder, preaching faith, repentance, and remission of sins, and teaching that the Holy Spirit is received by the laying on of hands. He was also called to serve as an agent for the church in a place the bishop would appoint, handling its business affairs. He was told to travel with Joseph Smith and Sidney Rigdon, with further duties to be revealed later according to his labor in the vineyard. The Lord closed by teaching that only those who endure to the end are saved.",
    context:"Given through Joseph Smith in June 1831 at Kirtland, answering Sidney Gilbert's request to know his calling and election in the church.",
    keyVerses:[
      { ref:"D&C 53:2", text:"Behold, I, the Lord, who was crucified for the sins of the world, give unto you a commandment that you shall forsake the world." },
      { ref:"D&C 53:3", text:"Take upon you mine ordination, even that of an elder, to preach faith and repentance and remission of sins, according to my word," },
      { ref:"D&C 53:7", text:"And again, I would that ye should learn that he only is saved who endureth unto the end. Even so. Amen." }
    ],
    takeaway:"Forsake the world, serve faithfully in your calling, and endure to the end.",
    quiz:[
      { q:"What did Sidney Gilbert ask the Lord to make known to him?", choices:["The best route to Missouri","How to operate the church storehouse","His calling and election in the church","The meaning of ancient prophecies"], a:2, why:"The Lord heard Gilbert's prayers concerning his calling and election in the church raised up in these last days." },
      { q:"Besides preaching as an elder, what role was Sidney Gilbert given?", choices:["Chief scribe for Joseph Smith","Bishop over the whole church","Captain of the traveling company","Agent unto the church in the place appointed by the bishop"], a:3, why:"Gilbert was appointed to be an agent unto the church in the place the bishop should appoint." },
      { q:"What principle did the Lord emphasize at the end of this revelation?", choices:["That he only is saved who endureth unto the end","That wealth is a sign of favor","That wisdom comes through formal schooling","That elders should remain in one place"], a:0, why:"The revelation closes by teaching that he only is saved who endureth unto the end." }
    ] },
  { n:54, summary:"When members of the Colesville branch broke the covenant they had made while settling at Thompson, Ohio, the Lord told Newel Knight to stand fast in his appointed office. He said the covenant had become void and of none effect, and that the brethren must repent of their sins and become truly humble and contrite if they wished to escape their enemies. The Lord pronounced woe on the man through whom the offense came and blessed those who had kept the covenant. Newel Knight was to lead the saints away from the land, appointing whom he would to pay their moneys, and journey westward to Missouri, to the borders of the Lamanites, seeking a living like other men until the Lord prepared a place for them.",
    context:"Given through Joseph Smith in June 1831 to Newel Knight after the covenant made by the Colesville saints at Thompson was broken.",
    keyVerses:[
      { ref:"D&C 54:6", text:"But blessed are they who have kept the covenant and observed the commandment, for they shall obtain mercy." },
      { ref:"D&C 54:10", text:"And again, be patient in tribulation until I come; and, behold, I come quickly, and my reward is with me, and they who have sought me early shall find rest to their souls. Even so. Amen." }
    ],
    takeaway:"Keep your covenants, repent quickly, and be patient in tribulation; those who seek the Lord early find rest.",
    quiz:[
      { q:"To whom was this revelation addressed?", choices:["Sidney Rigdon","Newel Knight","Edward Partridge","Martin Harris"], a:1, why:"The Lord addressed Newel Knight, telling him to stand fast in the office whereunto he had been appointed." },
      { q:"Where were the saints told to take their journey after fleeing their enemies?", choices:["Back to Colesville, New York","To a settlement near Detroit","Into the regions westward, to the land of Missouri, to the borders of the Lamanites","To Kirtland until persecution ceased"], a:2, why:"They were commanded to journey into the regions westward, to Missouri, unto the borders of the Lamanites." },
      { q:"What had become of the covenant made at Thompson, and what was required of the people?", choices:["It was renewed yearly, so nothing more was needed","It remained in force and guaranteed their inheritance","It was replaced by a law of tithing","It had become void and of none effect, and they needed to repent, becoming humble and contrite"], a:3, why:"The Lord declared the broken covenant void and told the brethren to repent of all their sins and become truly humble and contrite." }
    ] },
  { n:55, summary:"William W. Phelps was told he was called and chosen of the Lord. After being baptized with an eye single to God's glory, he would receive a remission of sins and the Holy Spirit by the laying on of hands, and Joseph Smith would ordain him an elder to preach repentance and remission of sins by baptism. He was promised power to give the Holy Spirit to those who came before him contrite, and he was ordained to assist Oliver Cowdery in the work of printing and in selecting and writing books for schools, so that little children might receive instruction. Phelps was to journey with Joseph Smith and Sidney Rigdon to be planted in the land of his inheritance, and Joseph Coe was told to go with them.",
    context:"Given through Joseph Smith in June 1831 at Kirtland, calling William W. Phelps to preach and to direct church printing and school books.",
    keyVerses:[
      { ref:"D&C 55:1", text:"Behold, thus saith the Lord unto you, my servant William, yea, even the Lord of the whole earth, thou art called and chosen;" },
      { ref:"D&C 55:3", text:"And on whomsoever you shall lay your hands, if they are contrite before me, you shall have power to give the Holy Spirit." },
      { ref:"D&C 55:4", text:"And again, you shall be ordained to assist my servant Oliver Cowdery to do the work of printing, and of selecting and writing books for schools in this church," }
    ],
    takeaway:"Offer your talents with an eye single to God's glory, and He will give you work to do.",
    quiz:[
      { q:"What work was William W. Phelps ordained to assist Oliver Cowdery in doing?", choices:["The work of printing and of selecting and writing books for schools","The work of laying out the city of Zion","Translating ancient records into English","Overseeing the construction of a meetinghouse"], a:0, why:"Phelps was ordained to assist Oliver Cowdery in printing and in selecting and writing books for schools so little children could receive instruction." },
      { q:"On whom could Phelps bestow the gift of the Holy Spirit?", choices:["On anyone who requested it","On those who were contrite before the Lord","Only on members of his own household","Only on newly baptized children"], a:1, why:"On whomsoever Phelps laid his hands, if they were contrite before the Lord, he would have power to give the Holy Spirit." },
      { q:"Why was Phelps to take his journey with Joseph Smith and Sidney Rigdon?", choices:["To escape creditors in the east","To recruit printers for Kirtland","So he could be planted in the land of his inheritance to do this work","To serve briefly as bishop in Ohio"], a:2, why:"Phelps was to journey with them so he could be planted in the land of his inheritance to do the printing work." }
    ] },
  { n:56, summary:"Because of the rebellions of the saints at Thompson, the Lord revoked the commandment pairing Selah J. Griffin with Newel Knight and instead sent Thomas B. Marsh speedily to Missouri with Selah J. Griffin, while Newel Knight stayed to lead those willing to go. Ezra Thayre was commanded to repent of his pride and selfishness or lose his place in the church, and the Lord promised to repay Joseph Smith any money he had to pay for others. The people were rebuked for counseling in their own ways and for sins that were not pardoned. The Lord pronounced woes on rich men who would not give substance to the poor and on greedy poor men who would not labor, but promised the poor who were pure in heart that they would see the kingdom of God coming in power and great glory to their deliverance.",
    context:"Given through Joseph Smith in June 1831, revoking earlier travel commandments because of the stiffneckedness and rebellion of the saints at Thompson.",
    keyVerses:[
      { ref:"D&C 56:2", text:"And he that will not take up his cross and follow me, and keep my commandments, the same shall not be saved." },
      { ref:"D&C 56:16", text:"Wo unto you rich men, that will not give your substance to the poor, for your riches will canker your souls;" },
      { ref:"D&C 56:19", text:"For behold, the Lord shall come, and his recompense shall be with him, and he shall reward every man, and the poor shall rejoice;" }
    ],
    takeaway:"Take up your cross and follow the Lord; whether rich or poor, give willingly and labor honestly.",
    quiz:[
      { q:"Who was newly commanded to take his journey speedily to Missouri after his earlier commandment was revoked?", choices:["Ezra Thayre","Heman Basset","Newel Knight","Thomas B. Marsh"], a:3, why:"The Lord revoked the commandment given to Thomas B. Marsh and Ezra Thayre and sent Marsh speedily to Missouri with Selah J. Griffin." },
      { q:"Why did the Lord revoke the commandment given to Selah J. Griffin and Newel Knight?", choices:["Because of the stiffneckedness and rebellions of the saints in Thompson","Because Griffin had fallen seriously ill","Because Missouri could not yet receive them","Because Knight requested to remain behind"], a:0, why:"The Lord revoked that commandment in consequence of the stiffneckedness of His people in Thompson and their rebellions." },
      { q:"What lamentation did the Lord say would come to rich men who refused to give to the poor?", choices:["That they had built barns too large for their harvests","That the harvest is past, the summer is ended, and their soul is not saved","That they had trusted friends who failed them","That no prophet had come to warn them"], a:1, why:"Their lamentation in the day of visitation would be that the harvest is past, the summer is ended, and their soul is not saved." }
    ] },
  { n:57, summary:"Arriving in Jackson County, Missouri, the elders learned by revelation that this was the land the Lord had appointed and consecrated for the gathering of the saints, the land of promise and the place for the city of Zion. The town then called Independence was named the center place, with a temple spot lying westward not far from the courthouse. The saints were instructed to purchase the surrounding lands for an everlasting inheritance. Sidney Gilbert was appointed to receive moneys as the church's agent, buy land, establish a store selling goods without fraud, and obtain a license to send goods to the people. Edward Partridge was to divide the saints' inheritance, William W. Phelps was established as printer, and Oliver Cowdery was to assist him in copying, correcting, and selecting writings.",
    context:"Given through Joseph Smith in August 1831 at Independence, Missouri, identifying the land of Zion and its center place.",
    keyVerses:[
      { ref:"D&C 57:2", text:"Wherefore, this is the land of promise, and the place for the city of Zion." },
      { ref:"D&C 57:3", text:"And thus saith the Lord your God, if you will receive wisdom here is wisdom. Behold, the place which is now called Independence is the center place; and a spot for the temple is lying westward, upon a lot which is not far from the courthouse." },
      { ref:"D&C 57:11", text:"And again, verily I say unto you, let my servant William W. Phelps be planted in this place, and be established as a printer unto the church." }
    ],
    takeaway:"Build Zion where the Lord appoints through honest trade, wise land purchases, and faithful labor.",
    quiz:[
      { q:"Which place did the Lord identify as the center place?", choices:["Far West, Missouri","Kirtland, Ohio","Independence, Missouri","Adam-ondi-Ahman"], a:2, why:"The Lord said the place then called Independence was the center place, with the temple spot lying westward near the courthouse." },
      { q:"What two-fold assignment did Sidney Gilbert receive in Zion?", choices:["Preside as bishop and judge the people","Write the history and keep the records","Direct the school and translate scriptures","Serve as the church's agent to buy lands and establish a store"], a:3, why:"Gilbert was to receive moneys and buy land as the church's agent and to establish a store, selling goods without fraud." },
      { q:"Why were the saints to purchase lands in and around Independence?", choices:["To obtain an everlasting inheritance for the gathering saints","To resell the land at a profit to newcomers","To satisfy a demand from county officials","To keep the site empty until the temple was built"], a:0, why:"Buying the lands was wisdom so the disciples could obtain them for an everlasting inheritance." }
    ] },
  { n:58, summary:"At Independence the Lord told the elders that blessings follow faithfulness in tribulation, for after much tribulation come the blessings. They had been sent to lay the foundation of Zion and bear record of the land, and a supper of the house of the Lord was prepared to which all nations would be invited, the poor, lame, blind, and deaf coming in to the marriage of the Lamb. Edward Partridge was selected as a judge in Israel to divide the heritage of God, while the saints were told to keep the laws of the land and be subject to the powers that be. The Lord declared it is not meet that He should command in all things, urging men to be anxiously engaged in a good cause and do much of their own free will. Martin Harris was made an example in laying his moneys before the bishop, and Sidney Rigdon was to write a description of Zion and dedicate the land and temple spot.",
    context:"Given through Joseph Smith in August 1831 at Independence, instructing the elders on the land of Zion after much tribulation.",
    keyVerses:[
      { ref:"D&C 58:4", text:"For after much tribulation come the blessings. Wherefore the day cometh that ye shall be crowned with much glory; the hour is not yet, but is nigh at hand." },
      { ref:"D&C 58:27", text:"Verily I say, men should be anxiously engaged in a good cause, and do many things of their own free will, and bring to pass much righteousness;" },
      { ref:"D&C 58:43", text:"By this ye may know if a man repenteth of his sins—behold, he will confess them and forsake them." }
    ],
    takeaway:"After much tribulation come blessings; be anxiously engaged in good causes of your own free will.",
    quiz:[
      { q:"What did the Lord promise would follow much tribulation?", choices:["Immediate deliverance from every enemy","The blessings, and a day when they would be crowned with much glory","Wealth equal to the richest in Independence","A period of rest without commandments"], a:1, why:"The Lord said after much tribulation come the blessings, and the day would come they would be crowned with much glory." },
      { q:"What did the Lord say of the servant who is compelled in all things?", choices:["He is safest under direction","He receives the greater reward","He is a slothful and not a wise servant and receives no reward","He will be given another chance at once"], a:2, why:"He that is compelled in all things is a slothful and not a wise servant and receiveth no reward." },
      { q:"How can a person know whether someone has truly repented of his sins?", choices:["He preaches publicly against his old sins","He moves to the land of Zion","He pays the bishop for his stewardship","He will confess his sins and forsake them"], a:3, why:"The Lord gave the sign that a repentant man will confess his sins and forsake them." }
    ] },
  { n:59, summary:"The Lord pronounced blessings on those who had come up to the land of Zion with an eye single to His glory: the living would inherit the earth and the dead would rest from their labors. He commanded the saints to love God with all their heart, might, mind, and strength, to love their neighbors as themselves, and to thank the Lord in all things, offering a broken heart and a contrite spirit as a sacrifice. They were to go to the house of prayer and offer up their sacraments on the Lord's holy day, resting from their labors and preparing food with singleness of heart so their fasting would be perfect and their joy full. The earth's abundance was made for man's benefit, to please the eye and gladden the heart, to be used with judgment and not to excess, and man offended God chiefly by failing to confess His hand in all things.",
    context:"Given through Joseph Smith in August 1831 at Independence, giving the law of the Lord for the saints in Zion.",
    keyVerses:[
      { ref:"D&C 59:9", text:"And that thou mayest more fully keep thyself unspotted from the world, thou shalt go to the house of prayer and offer up thy sacraments upon my holy day;" },
      { ref:"D&C 59:18", text:"Yea, all things which come of the earth, in the season thereof, are made for the benefit and the use of man, both to please the eye and to gladden the heart;" },
      { ref:"D&C 59:21", text:"And in nothing doth man offend God, or against none is his wrath kindled, save those who confess not his hand in all things, and obey not his commandments." }
    ],
    takeaway:"Love God, keep His holy day, give thanks in all things, and use the earth's bounty with judgment.",
    quiz:[
      { q:"What sacrifice were the saints to offer unto the Lord in righteousness?", choices:["That of a broken heart and a contrite spirit","Burnt offerings at an altar of stones","Firstborn animals of their herds","Gold and silver laid before the bishop"], a:0, why:"The Lord commanded them to offer the sacrifice of a broken heart and a contrite spirit in righteousness." },
      { q:"What did the Lord appoint the holy day to be for the saints?", choices:["A day for trade at the church store","A day to rest from labors and pay devotions unto the Most High","A day reserved for missionary journeys","A monthly day of public fasting only"], a:1, why:"The day was appointed to rest from labors and to pay devotions unto the Most High." },
      { q:"According to this revelation, against whom is the wrath of God kindled?", choices:["Against those who enjoy the fruits of the earth","Against those who labor six days each week","Against those who confess not His hand in all things and obey not His commandments","Against those who gather with their families"], a:2, why:"Man offends God only when he confesses not His hand in all things and obeys not His commandments." }
    ] },
  { n:60, summary:"As the elders prepared to return home from Missouri, the Lord said He was pleased they had come up to Zion, but some had displeased Him because they would not open their mouths, hiding the talent they had received for fear of man; if they were not more faithful, even that which they had would be taken away. The elders were to journey by water toward St. Louis, with Joseph Smith, Sidney Rigdon, and Oliver Cowdery continuing to Cincinnati to preach with loud voices, without wrath or doubting, while the rest went two by two, preaching not in haste among the congregations of the wicked. Edward Partridge was to impart money to the returning elders where needed. The Lord commanded that no one idle away his time or bury his talent, and that any who were not received should shake off the dust of their feet in secret as a testimony for the day of judgment.",
    context:"Given through Joseph Smith in August 1831 as the elders departed Missouri for their homes, cautioning against idleness and fear.",
    keyVerses:[
      { ref:"D&C 60:2", text:"But with some I am not well pleased, for they will not open their mouths, but they hide the talent which I have given unto them, because of the fear of man." },
      { ref:"D&C 60:3", text:"And it shall come to pass, if they are not more faithful unto me, it shall be taken away, even that which they have." },
      { ref:"D&C 60:13", text:"Behold, they have been sent to preach my gospel among the congregations of the wicked; wherefore, I give unto them a commandment, thus: Thou shalt not idle away thy time," }
    ],
    takeaway:"Open your mouth and use your talent; the fear of man wastes what the Lord has given.",
    quiz:[
      { q:"Why was the Lord not pleased with some of the returning elders?", choices:["They argued over precedence in the company","They refused the bishop's financial help","They were slow in preparing their canoes","They would not open their mouths and hid their talents for fear of man"], a:3, why:"Some were not well pleasing because they would not open their mouths, hiding the talent given them because of the fear of man." },
      { q:"Which city were Joseph Smith, Sidney Rigdon, and Oliver Cowdery to preach in on the way home?", choices:["Cincinnati","Pittsburgh","Detroit","St. Louis"], a:0, why:"They were sent from St. Louis toward Cincinnati, where they were to declare the word with loud voices." },
      { q:"What testimony were elders to leave in places where people refused to receive them?", choices:["A written warning posted in the marketplace","Shaking off the dust of their feet in secret and washing their feet","A refusal to ever pass that way again","A public list of the offenders' names"], a:1, why:"They were to shake off the dust of their feet in secret and wash their feet as a testimony against them in the day of judgment." }
    ] },
  { n:61, summary:"After a dangerous experience on the Missouri River, the Lord forgave the assembled elders their sins but said it was not needful for the whole company to move swiftly upon the waters while the inhabitants on either side were perishing in unbelief. He declared that many dangers and destructions were decreed upon the waters in the last days, though the faithful would not perish by them, and He warned the elders to forewarn their brethren, for the destroyer rideth upon the face of the waters. Sidney Gilbert and William W. Phelps were to press on in haste by water, while Joseph Smith, Sidney Rigdon, and Oliver Cowdery were to continue only on the canal and then travel by land, pitching their tents like the children of Israel. The Lord closed with comfort: be of good cheer, little children, for He was in their midst.",
    context:"Given through Joseph Smith in August 1831 on the Missouri River after the elders met dangers while traveling upon the waters.",
    keyVerses:[
      { ref:"D&C 61:6", text:"Nevertheless, all flesh is in mine hand, and he that is faithful among you shall not perish by the waters." },
      { ref:"D&C 61:15", text:"Wherefore, the days will come that no flesh shall be safe upon the waters." },
      { ref:"D&C 61:36", text:"And now, verily I say unto you, and what I say unto one I say unto all, be of good cheer, little children; for I am in your midst, and I have not forsaken you;" }
    ],
    takeaway:"Heed the Lord's warnings, travel faithfully by His counsel, and be of good cheer, for He has not forsaken you.",
    quiz:[
      { q:"What did the Lord say He had decreed upon the waters in the last days?", choices:["A special blessing for every voyager","Plenty of fish for the faithful","Many destructions, for the destroyer rideth upon the face thereof","Nothing, for the waters remained blessed"], a:2, why:"The Lord decreed many destructions upon the waters and said the destroyer rideth upon the face thereof." },
      { q:"How were Joseph Smith, Sidney Rigdon, and Oliver Cowdery to continue their journey home?", choices:["By water the entire distance to speed their return","By remaining in Missouri until spring","By separating to cover more ground","Only upon the canal, then journeying by land, pitching their tents by the way"], a:3, why:"They were told not to come upon the waters except the canal, then to journey by land like the children of Israel." },
      { q:"Why had the Lord suffered the elders to travel upon the waters at all?", choices:["That they might bear record, though there are many dangers upon the waters","Because no road existed along the river","Because they demanded a sign of His power","Because He had not yet warned them"], a:0, why:"The Lord suffered it that they might bear record, for there are many dangers upon the waters, especially hereafter." }
    ] },
  { n:62, summary:"Meeting elders who were still traveling toward Zion, the Lord identified Himself as their advocate who knows the weakness of man and how to succor those who are tempted. He said their mission was not yet full, but they were blessed, for the testimony they had borne was recorded in heaven for the angels to look upon, and their sins were forgiven. They were told to continue their journey, assemble on the land of Zion, hold a meeting, rejoice together, and offer a sacrament to the Most High before returning to bear record. The Lord explained He had brought them together so the faithful would be preserved and rejoice together in the land of Missouri, and He added that any who desired to ride horses, mules, or chariots might receive that blessing with a thankful heart.",
    context:"Given through Joseph Smith in August 1831 to elders still traveling toward Missouri, whom the returning company met on the road.",
    keyVerses:[
      { ref:"D&C 62:1", text:"Behold, and hearken, O ye elders of my church, saith the Lord your God, even Jesus Christ, your advocate, who knoweth the weakness of man and how to succor them who are tempted." },
      { ref:"D&C 62:3", text:"Nevertheless, ye are blessed, for the testimony which ye have borne is recorded in heaven for the angels to look upon; and they rejoice over you, and your sins are forgiven you." },
      { ref:"D&C 62:9", text:"Behold, the kingdom is yours. And behold, and lo, I am with the faithful always. Even so. Amen." }
    ],
    takeaway:"Bear testimony faithfully; it is recorded in heaven, and the Lord is with the faithful always.",
    quiz:[
      { q:"How did the Lord identify Himself at the opening of this revelation?", choices:["As the judge of quick and dead","As their advocate, who knoweth the weakness of man","As the light of the world","As the chief cornerstone"], a:1, why:"The Lord called Himself Jesus Christ, their advocate, who knows the weakness of man and how to succor the tempted." },
      { q:"What had become of the testimony these elders had borne?", choices:["It had been doubted by their brethren","It had to be repeated at a conference","It was recorded in heaven for the angels to look upon","It was entered only in local meeting minutes"], a:2, why:"Their testimony is recorded in heaven for the angels to look upon, and the angels rejoice over them." },
      { q:"Why did the Lord say He had brought these elders together?", choices:["To organize the first high council","To discipline them publicly for idleness","To decide who would stay in Missouri","So the faithful among them would be preserved and rejoice together in the land of Missouri"], a:3, why:"The Lord brought them together to fulfill His promise that the faithful would be preserved and rejoice together in Missouri." }
    ] },
  { n:63, summary:"Back in Kirtland, the Lord rebuked the people for seeking signs, teaching that faith cometh not by signs but that signs follow those that believe, and that signs come by faith and by the will of God, not the will of men. Adulterers were among them, and those who lusted after women in their hearts would lose the Spirit, while the fearful, unbelieving, liars, whoremongers, and sorcerers faced the second death. Those who endured in faith would receive an inheritance when the earth was transfigured, and commandment keepers would receive the mysteries of the kingdom, a well of living water. Zion's land was to be obtained by purchase rather than blood, for Satan stirred enemies to anger, while wars were decreed and the saints would hardly escape. The Lord reproved Sidney Rigdon for exalting himself and rejecting counsel, commanded sacred things to be spoken with care by the Spirit, and sent Oliver Cowdery to carry the sayings to Zion.",
    context:"Given through Joseph Smith in August 1831 in Kirtland, warning the saints against seeking signs, adultery, and hastening to Zion.",
    keyVerses:[
      { ref:"D&C 63:7", text:"And he that seeketh signs shall see signs, but not unto salvation." },
      { ref:"D&C 63:9", text:"But, behold, faith cometh not by signs, but signs follow those that believe." },
      { ref:"D&C 63:23", text:"But unto him that keepeth my commandments I will give the mysteries of my kingdom, and the same shall be in him a well of living water, springing up unto everlasting life." }
    ],
    takeaway:"Walk by faith rather than seeking signs; keep the commandments, for this is a day of warning.",
    quiz:[
      { q:"What did the Lord teach about the relationship between faith and signs?", choices:["Faith cometh not by signs, but signs follow those that believe","Signs are given first so that faith may follow","Signs belong only to the ancient apostles","Faith and signs have no connection"], a:0, why:"The Lord declared that faith cometh not by signs but signs follow those that believe, and signs come by faith, not by the will of men." },
      { q:"How did the Lord say the land of Zion could be obtained?", choices:["By petitioning the government for a grant","Only by purchase or by blood","By casting lots among the settlers","By waiting for the current owners to leave"], a:1, why:"Zion shall not be obtained but by purchase or by blood; if by purchase, they are blessed." },
      { q:"What did the Lord warn would happen to those who look on a woman to lust after her?", choices:["They would be removed from their stewardships","They would be required to pay restitution in land","They would not have the Spirit, but would deny the faith and fear","They would be barred from attending meetings"], a:2, why:"Such would not have the Spirit, but would deny the faith and fear." }
    ] },
  { n:64, summary:"At Kirtland the Lord forgave the elders their sins for His own glory and the salvation of souls, promising Joseph Smith that the keys of the mysteries of the kingdom would not be taken from him while he lived obediently. He taught that of us it is required to forgive all men, since the disciples of old were afflicted for forgiving not one another in their hearts. Ezra Booth and Isaac Morley were reproved, Edward Partridge was warned that Satan sought to destroy his soul, and Frederick G. Williams was told to keep his farm because the Lord would retain a stronghold in Kirtland for five years. The saints were told to labor while it is called today, for this is a day of sacrifice and the tithing of the Lord's people; he that is tithed shall not be burned at His coming. They were counseled not to be weary in well-doing, for out of small things proceedeth that which is great.",
    context:"Given through Joseph Smith in September 1831 in Kirtland, teaching forgiveness and steady labor while a great work was founded.",
    keyVerses:[
      { ref:"D&C 64:10", text:"I, the Lord, will forgive whom I will forgive, but of you it is required to forgive all men." },
      { ref:"D&C 64:33", text:"Wherefore, be not weary in well-doing, for ye are laying the foundation of a great work. And out of small things proceedeth that which is great." },
      { ref:"D&C 64:34", text:"Behold, the Lord requireth the heart and a willing mind; and the willing and obedient shall eat the good of the land of Zion in these last days." }
    ],
    takeaway:"Forgive all men, give the Lord your heart and a willing mind, and keep laboring while it is called today.",
    quiz:[
      { q:"Who was told not to sell his farm because the Lord would retain a stronghold in Kirtland?", choices:["Newel K. Whitney","Titus Billings","Isaac Morley","Frederick G. Williams"], a:3, why:"The Lord would not have Frederick G. Williams sell his farm, for He would retain a stronghold in Kirtland for five years." },
      { q:"What did the Lord say is required of us concerning forgiveness?", choices:["That we forgive all men","That we forgive only those who apologize","That we forgive once, but not repeatedly","That we leave all judgment to the bishop"], a:0, why:"The Lord will forgive whom He will forgive, but of us it is required to forgive all men." },
      { q:"Why did the Lord urge the saints not to be weary in well-doing?", choices:["Because their persecution would soon cease","Because they were laying the foundation of a great work, and out of small things proceedeth that which is great","Because the whole church would soon move to Missouri","Because their labors ended with the next conference"], a:1, why:"They were laying the foundation of a great work, and out of small things proceedeth that which is great." }
    ] },
  { n:65, summary:"The Lord gave a prayer through Joseph Smith declaring that the keys of the kingdom of God were committed unto man on the earth, and from thence the gospel would roll forth unto the ends of the earth like the stone cut out of the mountain without hands until it filled the whole earth. A voice cried for men to prepare the way of the Lord, prepare the supper of the Lamb, and make ready for the Bridegroom. The saints were urged to pray, call upon the Lord's holy name, make known His wonderful works, and call upon Him that His kingdom might go forth so the inhabitants of the earth would receive it and be prepared for the day the Son of Man would come down in glory to meet the kingdom of God set up on the earth. The prayer closed asking that the kingdom of God go forth and the kingdom of heaven come, that God might be glorified.",
    context:"Given through Joseph Smith in September 1831, a prayer that the kingdom of God might go forth and fill the whole earth.",
    keyVerses:[
      { ref:"D&C 65:2", text:"The keys of the kingdom of God are committed unto man on the earth, and from thence shall the gospel roll forth unto the ends of the earth," },
      { ref:"D&C 65:4", text:"Pray unto the Lord, call upon his holy name, make known his wonderful works among the people." },
      { ref:"D&C 65:6", text:"Wherefore, may the kingdom of God go forth, that the kingdom of heaven may come, that thou, O God, mayest be glorified in heaven so on earth," }
    ],
    takeaway:"Pray and labor for the kingdom of God to go forth, that the kingdom of heaven may come.",
    quiz:[
      { q:"What figure did the revelation use to describe the gospel rolling forth?", choices:["A river flowing to the sea","A great tree filling the valleys","The stone cut out of the mountain without hands","A lamp shining from a hilltop"], a:2, why:"The gospel rolls forth like the stone cut out of the mountain without hands until it fills the whole earth." },
      { q:"What was committed unto man on the earth according to this revelation?", choices:["The records of the ten tribes","Power to command the elements","The government of all nations","The keys of the kingdom of God"], a:3, why:"The keys of the kingdom of God are committed unto man on the earth, and from thence the gospel rolls forth." },
      { q:"Why were the saints told to call upon the Lord that His kingdom might go forth?", choices:["So the inhabitants of the earth would receive it and be prepared for the days to come","So the saints could govern the nations at once","So enemies would be destroyed immediately","So Missouri could be settled without trouble"], a:0, why:"The kingdom was to go forth so the inhabitants of the earth would receive it and be prepared for the days to come." }
    ] },
  { n:66, summary:"William E. McLellin was blessed for turning away from his iniquities and receiving the everlasting covenant, the fulness of the gospel, yet the Lord told him he was clean but not all and should repent of things not pleasing in the Lord's sight. McLellin was called to proclaim the gospel from land to land and city to city in regions where it had not been preached. He was not to go up to Zion as yet but to go to the eastern lands, bearing testimony in every place and reasoning with the people in their synagogues, with Samuel H. Smith as his companion whom he must not forsake. He was promised power to heal the sick if he laid his hands on them, was warned to forsake unrighteousness and commit not adultery, a temptation that had troubled him, and was promised that faithfulness to the end would bring a crown of eternal life.",
    context:"Given through Joseph Smith to William E. McLellin in Ohio in October 1831, answering his desire to know the Lord's will.",
    keyVerses:[
      { ref:"D&C 66:10", text:"Seek not to be cumbered. Forsake all unrighteousness. Commit not adultery—a temptation with which thou hast been troubled." },
      { ref:"D&C 66:11", text:"Keep these sayings, for they are true and faithful; and thou shalt magnify thine office, and push many people to Zion with songs of everlasting joy upon their heads." },
      { ref:"D&C 66:12", text:"Continue in these things even unto the end, and you shall have a crown of eternal life at the right hand of my Father, who is full of grace and truth." }
    ],
    takeaway:"Repent of what remains unclean, serve faithfully with your companion, and endure to receive a crown of eternal life.",
    quiz:[
      { q:"Which elder was commanded to travel with William E. McLellin to the eastern lands?", choices:["Orson Pratt","Samuel H. Smith","Lyman Johnson","Reynolds Cahoon"], a:1, why:"The Lord directed that Samuel H. Smith go with McLellin, who was not to forsake him." },
      { q:"Where was McLellin told not to go as yet?", choices:["Into the eastern lands","Among the synagogues of the people","Up unto the land of Zion","Back to his former trade"], a:2, why:"He was told to tarry not many days and go not up unto the land of Zion as yet." },
      { q:"What specific temptation did the Lord name for McLellin to overcome?", choices:["Doubting the revelations","Coveting his neighbor's property","Abandoning his companion on the road","Committing adultery"], a:3, why:"The Lord commanded him not to commit adultery, a temptation with which he had been troubled." }
    ] },
  { n:67, summary:"When the elders gathered to approve the revelations for publication, some struggled to accept them, and the Lord observed that there were fears in their hearts, which was why they had not received the promised blessing. He offered a testimony of the truth of the commandments lying before them: since they knew Joseph Smith's ordinary language and imperfections and had sought to express themselves beyond his ability, the wisest among them should take the least of the revelations in the Book of Commandments and try to write one like it. If they could not, they were under condemnation if they did not bear record that the revelations were true. The Lord promised that those ordained who stripped themselves of jealousies and fears and humbled themselves would have the veil rent and see Him with spiritual eyes, though the natural man cannot abide God's presence; they were to continue in patience until perfected.",
    context:"Given through Joseph Smith in November 1831 at Hiram, Ohio, as the elders weighed the revelations gathered for publication.",
    keyVerses:[
      { ref:"D&C 67:3", text:"Ye endeavored to believe that ye should receive the blessing which was offered unto you; but behold, verily I say unto you there were fears in your hearts," },
      { ref:"D&C 67:8", text:"But if ye cannot make one like unto it, ye are under condemnation if ye do not bear record that they are true." },
      { ref:"D&C 67:13", text:"Ye are not able to abide the presence of God now, neither the ministering of angels; wherefore, continue in patience until ye are perfected." }
    ],
    takeaway:"Trade fear for faith in the Lord's revelations, humble yourself, and continue in patience until you are perfected.",
    quiz:[
      { q:"Why had the elders not received the blessing offered to them?", choices:["Because there were fears in their hearts","Because they lacked the proper ordination","Because they were gathered in the wrong place","Because Joseph Smith withheld the manuscripts"], a:0, why:"They endeavored to believe, but there were fears in their hearts, and that was why they did not receive." },
      { q:"What test did the Lord propose concerning the commandments before them?", choices:["Reading them aloud without a single error","Having the most wise among them try to make one like the least of them","Matching them against every verse of the Bible","Waiting for a heavenly messenger to approve them"], a:1, why:"They were to seek out the least of the revelations and appoint the most wise among them to try to make one like it." },
      { q:"What were the ordained elders promised if they stripped themselves from jealousies and fears and humbled themselves before the Lord?", choices:["That no enemy would ever trouble them","That their own writings would join the revelations","That the veil would be rent and they would see and know the Lord","That they would translate sealed records"], a:2, why:"In humbling themselves from jealousies and fears, the veil would be rent and they would see and know that He is." }
    ] },
  { n:68, summary:"The Lord affirmed that Orson Hyde was called by his ordination to proclaim the everlasting gospel from people to people and land to land, an example for all ordained to the priesthood. Whatever they spoke when moved upon by the Holy Ghost would be scripture, the will, mind, word, and voice of the Lord, and the power of God unto salvation. Hyde, Luke Johnson, Lyman Johnson, William E. McLellin, and all faithful elders were sent into all the world to preach, baptize, and teach, with signs following and power to seal up unto eternal life. The revelation also directed that future bishops were to be worthy high priests appointed by the First Presidency unless a literal descendant of Aaron was found. Parents in Zion and her stakes were commanded to teach their children repentance, faith in Christ, baptism, and the Holy Ghost so children could be baptized at eight years old, and to keep the Sabbath holy, for idlers were among the people.",
    context:"Given through Joseph Smith in November 1831 at Hiram, Ohio, to four elders and on the duties of bishops and parents.",
    keyVerses:[
      { ref:"D&C 68:4", text:"And whatsoever they shall speak when moved upon by the Holy Ghost shall be scripture, shall be the will of the Lord, shall be the mind of the Lord," },
      { ref:"D&C 68:15", text:"Wherefore they shall be high priests who are worthy, and they shall be appointed by the First Presidency of the Melchizedek Priesthood, except they be literal descendants of Aaron." },
      { ref:"D&C 68:27", text:"And their children shall be baptized for the remission of their sins when eight years old, and receive the laying on of the hands." }
    ],
    takeaway:"Speak by the Holy Ghost, and teach children faith, repentance, and baptism from their earliest years.",
    quiz:[
      { q:"What did the Lord say words become when elders speak as they are moved upon by the Holy Ghost?", choices:["Helpful suggestions for the hearers","Commentaries on the written scriptures","Opinions to be tested by a vote","Scripture, the will, mind, word, and voice of the Lord"], a:3, why:"Words spoken when moved upon by the Holy Ghost are scripture, the will, mind, word, and voice of the Lord." },
      { q:"Who appoints bishops when no literal descendant of Aaron is found?", choices:["The First Presidency of the Melchizedek Priesthood","A vote of the local members","The standing high council in Zion","The eldest elder of the branch"], a:0, why:"Bishops are to be worthy high priests appointed by the First Presidency of the Melchizedek Priesthood unless a descendant of Aaron is found." },
      { q:"At what age were children in Zion and her stakes to be baptized for the remission of their sins?", choices:["Twelve years old","Eight years old","Ten years old","Sixteen years old"], a:1, why:"Children were to be baptized for the remission of their sins when eight years old and receive the laying on of hands." }
    ] }
);
